import sys

MOD = 998244353
PRIMITIVE_ROOT = 3

try:
    import numpy as np
except Exception:
    np = None


def naive_convolution(a, b):
    res = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                if bj:
                    res[i + j] = (res[i + j] + ai * bj) % MOD
    return res


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1]

    # Vertex 1 must be black and vertex 2N must be white.
    if S[0] != "B" or S[-1] != "W":
        print(0)
        return

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    black_pos = [i for i, c in enumerate(S) if c == "B"]

    # For j < N, T_j is the number of white vertices before black j+1.
    # Only strict increases of T_j give non-redundant constraints.
    xs = []  # black-count coordinate j
    ys = []  # white-count coordinate T_j
    cs = []  # T_j - j
    prev_t = 0
    for j in range(1, N):
        t = black_pos[j] - j
        if t > prev_t and t >= j:
            xs.append(j)
            ys.append(t)
            cs.append(t - j)
        prev_t = t

    # Artificial final equation; its solution is the answer.
    xs.append(N)
    ys.append(N)
    cs.append(0)

    m = len(xs)
    a = [0] * m
    add = [0] * m

    use_np = np is not None

    if m > 1:
        max_ntt = 1
        while max_ntt < 2 * N:
            max_ntt <<= 1

        half_max = max_ntt // 2
        g = pow(PRIMITIVE_ROOT, (MOD - 1) // max_ntt, MOD)
        roots = [1] * half_max
        for i in range(1, half_max):
            roots[i] = roots[i - 1] * g % MOD
        ig = pow(g, MOD - 2, MOD)
        iroots = [1] * half_max
        for i in range(1, half_max):
            iroots[i] = iroots[i - 1] * ig % MOD

        rev_cache = {}

        def get_rev(n):
            rev = rev_cache.get(n)
            if rev is None:
                rev = [0] * n
                for i in range(1, n):
                    rev[i] = (rev[i >> 1] >> 1) | ((i & 1) * (n >> 1))
                rev_cache[n] = rev
            return rev

        def ntt(a, invert):
            n = len(a)
            rev = get_rev(n)
            for i in range(1, n):
                j = rev[i]
                if i < j:
                    a[i], a[j] = a[j], a[i]

            length = 2
            src = iroots if invert else roots
            while length <= n:
                wlen = src[max_ntt // length]
                half = length >> 1
                for start in range(0, n, length):
                    w = 1
                    for i in range(start, start + half):
                        u = a[i]
                        v = a[i + half] * w % MOD
                        x = u + v
                        if x >= MOD:
                            x -= MOD
                        a[i] = x
                        x = u - v
                        if x < 0:
                            x += MOD
                        a[i + half] = x
                        w = w * wlen % MOD
                length <<= 1

            if invert:
                inv_n = pow(n, MOD - 2, MOD)
                for i in range(n):
                    a[i] = a[i] * inv_n % MOD

        def convolution_ntt(a, b):
            need = len(a) + len(b) - 1
            n = 1 << (need - 1).bit_length()
            fa = a + [0] * (n - len(a))
            fb = b + [0] * (n - len(b))
            ntt(fa, False)
            ntt(fb, False)
            for i in range(n):
                fa[i] = fa[i] * fb[i] % MOD
            ntt(fa, True)
            return fa[:need]

        if use_np:
            roots_np = np.array(roots, dtype=np.int64)
            iroots_np = np.array(iroots, dtype=np.int64)
            np_rev_cache = {}

            def ntt_np(arr, invert):
                n = arr.shape[0]
                rev = np_rev_cache.get(n)
                if rev is None:
                    rev = np.array(get_rev(n), dtype=np.int64)
                    np_rev_cache[n] = rev
                arr = arr[rev]

                length = 2
                src = iroots_np if invert else roots_np
                while length <= n:
                    half = length >> 1
                    step = max_ntt // length
                    w = src[::step][:half]
                    mat = arr.reshape(-1, length)
                    u = mat[:, :half].copy()
                    v = (mat[:, half:] * w) % MOD
                    mat[:, :half] = (u + v) % MOD
                    mat[:, half:] = (u - v) % MOD
                    length <<= 1

                if invert:
                    arr = (arr * pow(n, MOD - 2, MOD)) % MOD
                return arr

            def convolution_np(a, b):
                need = len(a) + len(b) - 1
                n = 1 << (need - 1).bit_length()
                fa = np.zeros(n, dtype=np.int64)
                fb = np.zeros(n, dtype=np.int64)
                fa[:len(a)] = a
                fb[:len(b)] = b
                fa = ntt_np(fa, False)
                fb = ntt_np(fb, False)
                fa = (fa * fb) % MOD
                fa = ntt_np(fa, True)
                return fa[:need].tolist()

        def convolution(a, b):
            if not a or not b:
                return []
            nonzero = 0
            for v in a:
                if v:
                    nonzero += 1
            if nonzero * len(b) <= 4096:
                return naive_convolution(a, b)
            if use_np:
                return convolution_np(a, b)
            return convolution_ntt(a, b)

        leaf_size = 64 if use_np else 128
        direct_limit = 4096 if use_np else 16384

        sys.setrecursionlimit(1 << 20)

        def cdq(l, r):
            if r - l <= leaf_size:
                for s in range(l, r):
                    val = fact[ys[s]] - add[s]
                    if val < 0:
                        val += MOD
                    av = val * invfact[cs[s]] % MOD
                    a[s] = av
                    if av:
                        x = xs[s]
                        for t in range(s + 1, r):
                            add[t] = (add[t] + av * fact[ys[t] - x]) % MOD
                return

            mid = (l + r) >> 1
            cdq(l, mid)

            left_cnt = mid - l
            right_cnt = r - mid

            if left_cnt * right_cnt <= direct_limit:
                for q in range(l, mid):
                    aq = a[q]
                    if aq:
                        xq = xs[q]
                        for s in range(mid, r):
                            add[s] = (add[s] + aq * fact[ys[s] - xq]) % MOD
            elif any(a[l:mid]):
                x0 = xs[l]
                x1 = xs[mid - 1]
                d0 = ys[mid] - x1
                d1 = ys[r - 1] - x0

                left_poly = [0] * (x1 - x0 + 1)
                for q in range(l, mid):
                    left_poly[xs[q] - x0] = a[q]
                right_poly = fact[d0:d1 + 1]

                conv = convolution(left_poly, right_poly)
                offset = x0 + d0
                for s in range(mid, r):
                    idx = ys[s] - offset
                    val = conv[idx]
                    if val:
                        nv = add[s] + val
                        if nv >= MOD:
                            nv -= MOD
                        add[s] = nv

            cdq(mid, r)

        cdq(0, m)
    else:
        a[0] = fact[ys[0]] * invfact[cs[0]] % MOD

    print(a[-1] % MOD)


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if k < -total or k > total:
            return -1

        off = total
        size = 2 * total + 1
        mask = (1 << size) - 1

        # dp0[p], dp1[p]: bitsets of alternating sums achievable with product p
        # and even/odd selected length. Bit i represents sum i - off.
        dp0 = [0] * (limit + 1)
        dp1 = [0] * (limit + 1)

        # States whose product already exceeded limit; only useful if a later 0 resets product to 0.
        over0 = 0
        over1 = 0

        def shift(bits: int, d: int) -> int:
            if d > 0:
                return (bits << d) & mask
            if d < 0:
                return bits >> (-d)
            return bits

        for x in nums:
            if x == 0:
                even = over0
                odd = over1
                for p in range(limit + 1):
                    b = dp0[p]
                    if b:
                        even |= b
                    b = dp1[p]
                    if b:
                        odd |= b

                # Selecting 0 keeps the alternating sum, flips parity, and makes product 0.
                if even:
                    dp1[0] |= even
                if odd:
                    dp0[0] |= odd
                dp1[0] |= 1 << off  # start [0]

            elif x == 1:
                o0, o1 = over0, over1
                if o0:
                    over1 |= shift(o0, 1)
                if o1:
                    over0 |= shift(o1, -1)

                for p in range(limit + 1):
                    b0 = dp0[p]
                    b1 = dp1[p]
                    if b0 or b1:
                        if b1:
                            dp0[p] |= shift(b1, -1)
                        if b0:
                            dp1[p] |= shift(b0, 1)

                dp1[1] |= 1 << (off + 1)  # start [1]

            else:
                add0 = [0] * (limit + 1)
                add1 = [0] * (limit + 1)
                ao0 = 0
                ao1 = 0

                for p in range(limit + 1):
                    b0 = dp0[p]
                    b1 = dp1[p]
                    if not (b0 or b1):
                        continue

                    s0 = shift(b0, x) if b0 else 0   # even length -> add x, becomes odd
                    s1 = shift(b1, -x) if b1 else 0  # odd length -> subtract x, becomes even
                    q = p * x

                    if q <= limit:
                        if s0:
                            add1[q] |= s0
                        if s1:
                            add0[q] |= s1
                    else:
                        if s0:
                            ao1 |= s0
                        if s1:
                            ao0 |= s1

                o0, o1 = over0, over1
                if o0:
                    ao1 |= shift(o0, x)
                if o1:
                    ao0 |= shift(o1, -x)

                for p in range(limit + 1):
                    a = add0[p]
                    if a:
                        dp0[p] |= a
                    a = add1[p]
                    if a:
                        dp1[p] |= a

                over0 |= ao0
                over1 |= ao1

                bit = 1 << (off + x)
                if x <= limit:
                    dp1[x] |= bit      # start [x]
                else:
                    over1 |= bit       # product already too large

        bit = 1 << (off + k)

        for p in range(limit, 0, -1):
            if (dp0[p] & bit) or (dp1[p] & bit):
                return p

        if (dp0[0] & bit) or (dp1[0] & bit):
            return 0

        return -1

import sys

OFF = 1_000_000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    T = data[0]
    idx = 1
    out = []

    for _ in range(T):
        R = data[idx]; B = data[idx + 1]
        idx += 2

        if (R & 1) or (R == 0 and (B & 1)):
            out.append("No")
            continue

        out.append("Yes")
        pts = []

        if R == 0:
            if B == 2:
                pts = [('B', 0, 0), ('B', 1, 1)]
            else:
                m = B // 2
                w = m - 1
                ad = [(a, 0) for a in range(w + 1)] + [(a, 1) for a in range(w, -1, -1)]
                pts = [('B', a + d, a - d) for a, d in ad]
        else:
            pts.append(('R', 0, 0))  # u

            if B > 0:
                if B & 1:
                    m = (B - 1) // 2
                    ad = [(a, 0) for a in range(m + 1)] + [(a, -1) for a in range(m, 0, -1)]
                else:
                    m = B // 2
                    ad = [(a, 0) for a in range(-1, m)] + [(a, -1) for a in range(m - 1, 0, -1)]
                for a, d in ad:
                    pts.append(('B', a + d + 1, a - d))

            pts.append(('R', 0, 1))  # v

            k = (R - 2) // 2
            for i in range(1, k + 1):
                pts.append(('R', -i, 1))
            for i in range(k, 0, -1):
                pts.append(('R', -i, 0))

        for ch, r, c in pts:
            out.append(f"{ch} {r + OFF} {c + OFF}")

    sys.stdout.write("\n".join(out))

