from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        if not queries:
            return 0

        max_r = max(r for _, r in queries)
        pow4 = [1]
        while pow4[-1] <= max_r:
            pow4.append(pow4[-1] * 4)

        def prefix(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            # Numbers in [4^(k-1), 4^k - 1] need k divisions by 4.
            for k in range(1, len(pow4)):
                lo = pow4[k - 1]
                if lo > n:
                    break
                hi = min(pow4[k] - 1, n)
                total += (hi - lo + 1) * k
            return total

        ans = 0
        for l, r in queries:
            work = prefix(r) - prefix(l - 1)
            height = (r.bit_length() + 1) // 2
            ans += max((work + 1) // 2, height)

        return ans

