import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); M = int(next(it))
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * (N + 1)
    odd_components = 0
    even_fixed = 0

    for s in range(1, N + 1):
        if color[s] != -1:
            continue
        color[s] = 0
        q = deque([s])
        cnt = [0, 0]
        while q:
            u = q.popleft()
            cnt[color[u]] += 1
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
        n = cnt[0] + cnt[1]
        if n & 1:
            odd_components += 1
        else:
            even_fixed ^= (cnt[0] & 1)

    if N & 1:
        win = (M & 1) == 1
    else:
        win = ((M & 1) ^ even_fixed ^ ((odd_components // 2) & 1)) == 1

    sys.stdout.write("Aoki\n" if win else "Takahashi\n")

