class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        return self._count(r) - self._count(l - 1)

    def _count(self, x: int) -> int:
        if x <= 0:
            return 0

        digits = [int(c) for c in str(x)]
        m = len(digits)
        all_nine = all(d == 9 for d in digits)

        fact = [1] * 11
        for i in range(1, 11):
            fact[i] = fact[i - 1] * i

        pw = [[1] * 11 for _ in range(10)]
        for d in range(1, 10):
            for e in range(1, 11):
                pw[d][e] = pw[d][e - 1] * d

        counts = [0] * 10
        total = 0
        ans = 0

        def perm_from(rem, k):
            den = 1
            for c in rem:
                den *= fact[c]
            return fact[k] // den

        def all_arrangements():
            den = 1
            for c in counts:
                den *= fact[c]
            res = fact[total] // den
            if counts[0]:
                den0 = fact[counts[0] - 1]
                for d in range(1, 10):
                    den0 *= fact[counts[d]]
                res -= fact[total - 1] // den0
            return res

        def bounded_arrangements():
            rem = counts[:]
            res = 0
            for i, lim in enumerate(digits):
                lo = 1 if i == 0 else 0
                for d in range(lo, lim):
                    if rem[d]:
                        rem[d] -= 1
                        res += perm_from(rem, total - i - 1)
                        rem[d] += 1
                if rem[lim] == 0:
                    return res
                rem[lim] -= 1
            return res + 1

        def dfs(d, left):
            nonlocal total, ans
            if d == 10:
                if total == 0:
                    return

                ssum = 0
                for dig, c in enumerate(counts):
                    if c:
                        ssum += dig * c
                if ssum == 0:
                    return

                if counts[0]:
                    prod = 0
                else:
                    prod = 1
                    for dig in range(1, 10):
                        c = counts[dig]
                        if c:
                            prod *= pw[dig][c]

                if prod % ssum:
                    return

                if total < m or (total == m and all_nine):
                    ans += all_arrangements()
                else:
                    ans += bounded_arrangements()
                return

            for c in range(left + 1):
                counts[d] = c
                total += c
                dfs(d + 1, left - c)
                total -= c
            counts[d] = 0

        dfs(0, m)
        return ans

from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [dict()]
        cnt = [0]
        depth = [0]
        end_node = [0] * n
        max_depth = 0

        for i, w in enumerate(words):
            u = 0
            for ch in w:
                v = children[u].get(ch)
                if v is None:
                    v = len(children)
                    children[u][ch] = v
                    children.append(dict())
                    cnt.append(0)
                    depth.append(depth[u] + 1)
                u = v
                cnt[u] += 1
            end_node[i] = u
            if depth[u] > max_depth:
                max_depth = depth[u]

        m = len(children)
        good_cnt = [0] * (max_depth + 1)
        unique_good = [-1] * (max_depth + 1)

        for u in range(1, m):
            d = depth[u]
            if cnt[u] >= k:
                good_cnt[d] += 1
                if good_cnt[d] == 1:
                    unique_good[d] = u
                else:
                    unique_good[d] = -1

        size = 1
        while size < max_depth + 1:
            size <<= 1
        tree = [-1] * (2 * size)

        for d in range(1, max_depth + 1):
            if good_cnt[d]:
                tree[size + d] = d
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update(pos: int, val: int) -> None:
            i = size + pos
            tree[i] = val
            i //= 2
            while i:
                tree[i] = max(tree[2 * i], tree[2 * i + 1])
                i //= 2

        ans_node = [0] * m
        stack = [(0, 0, 0, 0)]  # node, best_on_path_before, state(0=enter,1=exit), toggled

        while stack:
            u, best_before, state, toggled = stack.pop()
            if state == 0:
                if u == 0:
                    for v in children[0].values():
                        stack.append((v, 0, 0, 0))
                else:
                    d = depth[u]
                    toggled = (good_cnt[d] == 1 and unique_good[d] == u)
                    if toggled:
                        update(d, -1)

                    best = d if cnt[u] >= k + 1 else best_before
                    off = tree[1]
                    ans_node[u] = best if best >= off else off

                    stack.append((u, 0, 1, toggled))
                    for v in children[u].values():
                        stack.append((v, best, 0, 0))
            else:
                if toggled:
                    update(depth[u], depth[u])

        return [ans_node[end_node[i]] for i in range(n)]

