import math

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])

    d = 1
    while d * d * d < N:
        if N % d == 0:
            q = N // d
            D = 3 * (4 * q - d * d)
            r = math.isqrt(D)
            if r * r == D:
                num = r - 3 * d
                if num > 0 and num % 6 == 0:
                    y = num // 6
                    x = y + d
                    if x * x * x - y * y * y == N:
                        sys.stdout.write(f"{x} {y}")
                        return
        d += 1

    sys.stdout.write("-1")

