import sys
from collections import deque

sys.setrecursionlimit(10000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.g[v])):
            self.it[v] = i
            to, cap, rev = self.g[v][i]
            if cap > 0 and self.level[v] < self.level[to]:
                ret = self.dfs(to, t, f if f < cap else cap)
                if ret:
                    self.g[v][i][1] -= ret
                    self.g[to][rev][1] += ret
                    return ret
        return 0

    def max_flow(self, s, t, limit=None):
        flow = 0
        INF = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF)
                if f == 0:
                    break
                flow += f
                if limit is not None and flow >= limit:
                    return flow
        return flow


def min_edges_to_raise(N, edges, K, L):
    if L == 0:
        return 0
    S = N * L
    T = S + 1
    din = Dinic(T + 1)
    INF = 10**9

    def idx(v, i):  # v: 0-based, i: 1..L
        return v * L + (i - 1)

    for v in range(N):
        for i in range(1, L):
            din.add_edge(idx(v, i), idx(v, i + 1), INF)

    for u, v in edges:
        for i in range(1, L + 1):
            din.add_edge(idx(u, i), idx(v, i), 1)
        for i in range(1, L):
            din.add_edge(idx(u, i), idx(v, i + 1), INF)

    for i in range(1, L + 1):
        din.add_edge(S, idx(0, i), INF)
        din.add_edge(idx(N - 1, i), T, INF)

