class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_high = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for i, (a, b) in enumerate(conflictingPairs):
            lo, hi = (a, b) if a < b else (b, a)
            by_high[hi].append((lo, i))

        gain = [0] * m
        total = 0

        max1 = 0      # largest active low
        max2 = 0      # second largest active low
        max_cnt = 0   # how many active pairs have low == max1
        max_id = -1   # unique pair achieving max1, if max_cnt == 1

        for r in range(1, n + 1):
            for lo, i in by_high[r]:
                if lo > max1:
                    max2 = max1
                    max1 = lo
                    max_cnt = 1
                    max_id = i
                elif lo == max1:
                    max_cnt += 1
                    if max_cnt > 1:
                        max_id = -1
                elif lo > max2:
                    max2 = lo

            total += r - max1

            if max_cnt == 1:
                gain[max_id] += max1 - max2

        return total + max(gain)

