from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side

        def to_perimeter(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        pos = sorted(to_perimeter(x, y) for x, y in points)
        n = len(pos)

        def ok(d: int) -> bool:
            if d == 0:
                return True
            if k * d > L:
                return False

            b = pos + [p + L for p in pos]
            m = 2 * n
            nxt = [m] * m

            r = 0
            for i in range(m):
                if r < i + 1:
                    r = i + 1
                limit = b[i] + d
                while r < m and b[r] < limit:
                    r += 1
                nxt[i] = r

            for start in range(n):
                cur = start
                end_limit = start + n
                valid = True
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= end_limit:
                        valid = False
                        break
                if valid and b[cur] - b[start] <= L - d:
                    return True
            return False

        lo, hi = 0, L // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

