    while stack:
        v = stack.pop()
        order.append(v)
        pv = parent[v]
        for w in adj[v]:
            if w == pv:
                continue
            parent[w] = v
            stack.append(w)

    down = [1] * (n + 1)
    for v in reversed(order):
        vals = []
        for w in adj[v]:
            if parent[w] == v:
                vals.append(down[w])
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[v] = 1 + vals[0] + vals[1] + vals[2]
        else:
            down[v] = 1

    up = [1] * (n + 1)
    ans = -1
    for v in order:
        items = []
        pv = parent[v]
        for w in adj[v]:
            if w == pv:
                items.append((up[v], w))
            else:
                items.append((down[w], w))
        if not items:
            continue

        items.sort(key=lambda x: x[0], reverse=True)

        if items[0][0] > 1:
            cand = 1 + items[0][0]
            if cand > ans:
                ans = cand

        m = len(items)
        if m >= 4:
            cand = 1 + items[0][0] + items[1][0] + items[2][0] + items[3][0]
            if cand > ans:
