class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)

        def occurrences(text: str, pat: str):
            m = len(pat)
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pat[i] == pat[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1

            res = []
            i = j = 0
            while i < n:
                if text[i] == pat[j]:
                    i += 1
                    j += 1
                    if j == m:
                        res.append(i - m)
                        j = lps[j - 1]
                else:
                    if j:
                        j = lps[j - 1]
                    else:
                        i += 1
            return res

        first_star = p.find('*')
        second_star = p.find('*', first_star + 1)

        parts = [p[:first_star], p[first_star + 1:second_star], p[second_star + 1:]]
        parts = [(part, len(part)) for part in parts if part]

        if not parts:
            return 0

        occs = [occurrences(s, part) for part, _ in parts]
        if any(not occ for occ in occs):
            return -1

        if len(parts) == 1:
            return parts[0][1]

        if len(parts) == 2:
            (x, lx), (y, ly) = parts
            ox, oy = occs
            ans = 10 ** 18
            ptr = 0
            for sy in oy:
                limit = sy - lx
                while ptr < len(ox) and ox[ptr] <= limit:
                    ptr += 1
                if ptr:
                    ans = min(ans, sy + ly - ox[ptr - 1])
            return -1 if ans == 10 ** 18 else ans

        (a, la), (b, lb), (c, lc) = parts
        oa, ob, oc = occs

        left = [-1] * (n + 1)
        ptr = 0
        best = -1
        for pos in range(n + 1):
            while ptr < len(oa) and oa[ptr] + la <= pos:
                best = oa[ptr]
                ptr += 1
            left[pos] = best

        right = [-1] * (n + 1)
        idx = len(oc) - 1
        nxt = -1
        for pos in range(n, -1, -1):
            while idx >= 0 and oc[idx] >= pos:
                nxt = oc[idx]
                idx -= 1
            right[pos] = nxt

        ans = 10 ** 18
        for start_b in ob:
            start_a = left[start_b]
            start_c = right[start_b + lb]
            if start_a != -1 and start_c != -1:
                ans = min(ans, start_c + lc - start_a)

        return -1 if ans == 10 ** 18 else ans

