import math

MOD = 998244353
MAXA = 1000


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:]))

    spf = list(range(MAXA + 1))
    for i in range(2, int(MAXA ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAXA + 1, i):
                if spf[j] == j:
                    spf[j] = i

    occ = [[] for _ in range(MAXA + 1)]
    for idx, a in enumerate(A, 1):
        x = a
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            occ[p].append((idx, e))

    ans = 1

    for p in range(2, MAXA + 1):
        lst = occ[p]
        if not lst:
            continue

        m = len(lst)
        lengths = [0] * (m + 1)
        weights = [0] * m
        prev = 0
        for k, (i, e) in enumerate(lst):
            lengths[k] = i - prev
            weights[k] = e
            prev = i
        lengths[m] = N - prev

        g = 0
        for w in weights:
            g = math.gcd(g, w)
        if g > 1:
            weights = [w // g for w in weights]

        q = pow(p, g, MOD)
        T = sum(weights)

        pow1 = [1] * (T + 1)
        for h in range(1, T + 1):
            pow1[h] = pow1[h - 1] * q % MOD

        def pw_list(l):
            if l == 1:
                return pow1
            base = pow(q, l, MOD)
            arr = [1] * (T + 1)
            for h in range(1, T + 1):
                arr[h] = arr[h - 1] * base % MOD
            return arr

        L = [0] * (m + 1)
        L[0] = 1
        dp = [0] * (T + 1)
        arr = pw_list(lengths[0])
        for h in range(1, T + 1):
            dp[h] = arr[h]

        for k in range(1, m + 1):
            w = weights[k - 1]
            arr = pw_list(lengths[k])
            new = [0] * (T + 1)
            land = 0
            for h in range(1, T + 1):
                val = dp[h]
                if val:
                    h2 = h + w
                    if h2 <= T:
                        new[h2] = (new[h2] + val * arr[h2]) % MOD
                    if h >= w:
                        h2 = h - w
                        if h2 == 0:
                            land = (land + val) % MOD
                        else:
                            new[h2] = (new[h2] + val * arr[h2]) % MOD
            L[k] = land
            dp = new

        R = [0] * (m + 1)
        R[m] = 1
        G = pw_list(lengths[m])

        for r in range(m - 1, -1, -1):
            w = weights[r]
            R[r] = G[w]
            if r == 0:
                break
            arr = pw_list(lengths[r])
            cur = [0] * (T + 1)
            for h in range(T + 1):
                s = 0
                h2 = h + w
                if h2 <= T:
                    s = G[h2]
                h3 = h - w
                if h3 >= 0:
                    s += G[h3]
                    if s >= MOD:
                        s -= MOD
                if s:
                    cur[h] = arr[h] * s % MOD
            G = cur

        F = 0
        for r in range(m + 1):
            F = (F + L[r] * R[r]) % MOD
        ans = ans * F % MOD

    print(ans)


