class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        a = [ord(c) - 97 for c in caption]
        INF = 10 ** 9

        # pref[x][i] = cost to make caption[:i] all letter x
        pref = [array('i', [0]) for _ in range(26)]
        for k, ch in enumerate(a):
            for x in range(26):
                d = ch - x
                if d < 0:
                    d = -d
                pref[x].append(pref[x][k] + d)

        # best[x][p] = min cost of a run of letter x starting at p with length >= 3,
        # plus an optimal good suffix after it.
        best = [array('i', [INF]) * (n + 1) for _ in range(26)]
        g = [INF] * (n + 1)  # g[p]: min cost for suffix caption[p:] with no open run
        g[n] = 0

        suf = [pref[x][n] for x in range(26)]  # min(pref[x][j] + g[j]) for j >= p+3
        for p in range(n - 3, -1, -1):
            gp = INF
            for x in range(26):
                sx = suf[x]
                if sx < INF:
                    val = sx - pref[x][p]
                    best[x][p] = val
                    if val < gp:
                        gp = val
            g[p] = gp

            idx = p + 2
            if idx <= n and g[idx] < INF:
                base = g[idx]
                for x in range(26):
                    val = pref[x][idx] + base
                    if val < suf[x]:
                        suf[x] = val

        # For each p, smallest and second-smallest values among best[x][p].
        first = [INF] * n
        second = [INF] * n
        first_ch = [-1] * n
        for p in range(n):
            v1 = INF
            v2 = INF
            c1 = -1
            for x in range(26):
                v = best[x][p]
                if v < v1:
                    v2 = v1
                    v1 = v
                    c1 = x
                elif v < v2:
                    v2 = v
            first[p] = v1
            second[p] = v2
            first_ch[p] = c1

        # H[l][p]: min cost for suffix caption[p:] when the previous run has letter l
        # and is already valid (length >= 3), so it may continue or close.
        H = [array('i', [INF]) * (n + 1) for _ in range(26)]
        for l in range(26):
            H[l][n] = 0

        for p in range(n - 1, -1, -1):
            ap = a[p]
            v1 = first[p]
            v2 = second[p]
            c1 = first_ch[p]
            for l in range(26):
                close = v2 if l == c1 else v1
                cont = INF
                hp1 = H[l][p + 1]
                if hp1 < INF:
                    d = ap - l
                    if d < 0:
                        d = -d
                    cont = d + hp1
                H[l][p] = close if close < cont else cont

        def remaining(p: int, l: int, run: int) -> int:
            # run is capped at 3; run 1/2 means the current run still needs letters.
            if run == 3:
                return H[l][p]
            need = 3 - run
            q = p + need
            if q > n:
                return INF
            hq = H[l][q]
            if hq >= INF:
                return INF
            return pref[l][q] - pref[l][p] + hq

        total = g[0]
        if total >= INF:
            return ""

        res = []
        last = -1
        run = 0  # 0: no open run, 1/2: must continue, 3: valid and may close/continue
        rem = total

        for p in range(n):
            ap = a[p]
            chosen = -1

            if run == 0:
                lo, hi = 0, 26
            elif run < 3:
                lo, hi = last, last + 1
            else:
                lo, hi = 0, 26

            for x in range(lo, hi):
                d = ap - x
                if d < 0:
                    d = -d

                if run == 0:
                    nl, nr = x, 1
                elif run < 3:
                    nl, nr = last, run + 1
                else:
                    if x == last:
                        nl, nr = last, 3
                    else:
                        nl, nr = x, 1

                if nr == 3:
                    nrem = H[nl][p + 1]
                else:
                    need = 3 - nr
                    q = p + 1 + need
                    if q > n:
                        nrem = INF
                    else:
                        hq = H[nl][q]
                        if hq >= INF:
                            nrem = INF
                        else:
                            nrem = pref[nl][q] - pref[nl][p + 1] + hq

                if d + nrem == rem:
                    chosen = x
                    rem = nrem
                    last = nl
                    run = nr
                    res.append(chr(97 + x))
                    break

            if chosen < 0:
                return ""

        return "".join(res)

import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    s = data[2]

    size = 1 << n

    # popcount table
    pop = [0] * size
    for mask in range(1, size):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    # trans[mask] = list of (next_mask, multiplicity) over the 26 letters
    trans = [None] * size
    for mask in range(size):
        d = [0] * (n + 1)
        for j in range(1, n + 1):
            d[j] = d[j - 1] + ((mask >> (j - 1)) & 1)

        cntmap = {}
        for ci in range(26):
            c = chr(97 + ci)
            nmask = 0
            prev = 0  # nd[j-1]
            for j in range(1, n + 1):
                val = prev
                if d[j] > val:
                    val = d[j]
                if s[j - 1] == c:
                    cand = d[j - 1] + 1
                    if cand > val:
                        val = cand
                if val > prev:
                    nmask |= 1 << (j - 1)
                prev = val
            cntmap[nmask] = cntmap.get(nmask, 0) + 1
        trans[mask] = list(cntmap.items())

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        ndp = [0] * size
        for mask, cnt in enumerate(dp):
            if cnt:
                for nm, mult in trans[mask]:
                    ndp[nm] = (ndp[nm] + cnt * mult) % MOD
        dp = ndp

    ans = [0] * (n + 1)
    for mask, cnt in enumerate(dp):
        if cnt:
            ans[pop[mask]] = (ans[pop[mask]] + cnt) % MOD

    print(" ".join(map(str, ans)))

