def build_primes(limit=31623):
    is_prime = bytearray(b"\x01") * (limit + 1)
    is_prime[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            is_prime[i*i::i] = b"\x00" * (((limit - i*i) // i) + 1)
    return [i for i, v in enumerate(is_prime) if v]

PRIMES = build_primes()

def factor(n):
    res = []
    for p in PRIMES:
        if p * p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            res.append((p, e))
    if n > 1:
        res.append((n, 1))
    return res

def solve_one(n):
    if n == 1:
        return 1, 1
    x = 0
    mod = 1
    for p, e in factor(n):
        if p == 2:
            if e == 1:
                m, r = 4, 3
            else:
                m, r = 1 << (e + 2), 5
        else:
            m = pow(p, e + 1)
            r = p + 1
        newmod = mod * m
        t = ((r - x) % m) * pow(mod % m, -1, m) % m
        x = (x + mod * t) % newmod
        mod = newmod
    if x == 0:
        x = mod
    return x, mod

