from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        s = k - 1

        def tri(t: int) -> int:
            if t < 0:
                return 0
            return (t + 1) * (t + 2) // 2

        def bounded_pairs(a: int, b: int) -> int:
            # Count (x, y) with 0 <= x < a, 0 <= y < b, x + y <= s
            return tri(s) - tri(s - a) - tri(s - b) + tri(s - a - b)

        prev_greater = [-1] * n
        next_greater_equal = [n] * n

        st = []
        for i, x in enumerate(nums):
            while st and nums[st[-1]] <= x:
                st.pop()
            prev_greater[i] = st[-1] if st else -1
            st.append(i)

        st.clear()
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while st and nums[st[-1]] < x:
                st.pop()
            next_greater_equal[i] = st[-1] if st else n
            st.append(i)

        prev_smaller = [-1] * n
        next_smaller_equal = [n] * n

        st.clear()
        for i, x in enumerate(nums):
            while st and nums[st[-1]] >= x:
                st.pop()
            prev_smaller[i] = st[-1] if st else -1
            st.append(i)

        st.clear()
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while st and nums[st[-1]] > x:
                st.pop()
            next_smaller_equal[i] = st[-1] if st else n
            st.append(i)

        ans = 0
        for i, x in enumerate(nums):
            max_cnt = bounded_pairs(i - prev_greater[i], next_greater_equal[i] - i)
            min_cnt = bounded_pairs(i - prev_smaller[i], next_smaller_equal[i] - i)
            ans += x * (max_cnt + min_cnt)

        return ans

import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    P = int(data[1])

    k = N // 2
    D = N * (N - 1) // 2
    E = D + 1  # evaluation points 0,...,D

    fact = [1] * (D + 1)
    for i in range(1, D + 1):
        fact[i] = fact[i - 1] * i % P

    invfac = [1] * (N + 1)
    invfac[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfac[i - 1] = invfac[i] * i % P

    # weights[s][t][x]: value at x of
    # (1+X)^(t choose 2) * ((1+X)^s - 1)^t / t!
    weights = [[None] * N for _ in range(N)]
    for s in range(1, N):
        base = [(pow(x + 1, s, P) - 1) % P for x in range(E)]
        internal = [1] * E       # (1+x)^(t choose 2)
        cross = base[:]          # ((1+x)^s-1)^t
        xp_power = [1] * E       # (1+x)^t, used to update internal
        for t in range(1, N - s):
            sc = invfac[t]
            weights[s][t] = [
                internal[x] * cross[x] % P * sc % P
                for x in range(E)
            ]
            for x in range(E):
                xp = x + 1
                xp_power[x] = xp_power[x] * xp % P
                internal[x] = internal[x] * xp_power[x] % P
                cross[x] = cross[x] * base[x] % P

    # dp[p][a][b][s]:
    # p=0: last BFS layer is even; p=1: odd.
    # a = non-root vertices at even distance, b = vertices at odd distance,
    # s = size of the last layer.  Values are polynomial evaluations.
    dp = [
        [[[None] * N for _ in range(k + 1)] for _ in range(k)]
        for _ in range(2)
    ]
    dp[0][0][0][1] = [1] * E

    for a in range(k):
        for b in range(k + 1):
            # Last layer is even; add an odd layer.
            limit = k - b
            if limit:
                if a == 0:
                    s_iter = (1,) if b == 0 else ()
                else:
                    s_iter = range(1, a + 1)
                for s in s_iter:
                    src = dp[0][a][b][s]
                    if src is None:
                        continue
                    wrow = weights[s]
                    for t in range(1, limit + 1):
                        wt = wrow[t]
                        tgt = dp[1][a][b + t][t]
                        if tgt is None:
                            tgt = [0] * E
                            dp[1][a][b + t][t] = tgt
                        for e in range(E):
                            tgt[e] = (tgt[e] + src[e] * wt[e]) % P

            # Last layer is odd; add an even layer.
            limit = k - 1 - a
            if limit and b:
                for s in range(1, b + 1):
                    src = dp[1][a][b][s]
                    if src is None:
                        continue
                    wrow = weights[s]
                    for t in range(1, limit + 1):
                        wt = wrow[t]
                        tgt = dp[0][a + t][b][t]
                        if tgt is None:
                            tgt = [0] * E
                            dp[0][a + t][b][t] = tgt
                        for e in range(E):
                            tgt[e] = (tgt[e] + src[e] * wt[e]) % P

    y = [0] * E
    for p in range(2):
        for s in range(1, N):
            poly = dp[p][k - 1][k][s]
            if poly is not None:
                for e in range(E):
                    y[e] = (y[e] + poly[e]) % P

    # Convert exponential layer-label weights to labeled graphs.
    fn = fact[N - 1]
    y = [v * fn % P for v in y]

    # Interpolate coefficients from values at 0,...,D.
    # A(x) = product_{j=0}^D (x-j).
    A = [1]
    for l in range(E):
        new = [0] * (len(A) + 1)
        for i, c in enumerate(A):
            new[i] = (new[i] - l * c) % P
            new[i + 1] = (new[i + 1] + c) % P
        A = new

    coeff = [0] * E
    for j, yj in enumerate(y):
        if not yj:
            continue

        # Q(x) = A(x)/(x-j).
        Q = [0] * E
        qi = 0
        for i in range(E, 0, -1):
            qi = (A[i] + j * qi) % P
            Q[i - 1] = qi

        den = fact[j] * fact[D - j] % P
        if (D - j) & 1:
            den = (-den) % P
        scale = yj * pow(den, P - 2, P) % P

        for m in range(E):
            coeff[m] = (coeff[m] + scale * Q[m]) % P

    ans = [str(coeff[m] % P) for m in range(N - 1, D + 1)]
    sys.stdout.write(" ".join(ans))

if __name__ == "__main__":
    main()

