def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, p = data[0], data[1]
    A = []
    idx = 2
    for _ in range(n):
        A.append(data[idx:idx+n])
        idx += n

    if p == 2:
        v = str(n & 1)
        line = ' '.join([v] * n)
        sys.stdout.write('\n'.join([line] * n))
        return

    def mul(X, Y, mod):
        m = len(X)
        rn = range(m)
        res = [None] * m
        for i in rn:
            acc = [0] * m
            Xi = X[i]
            for k in rn:
                a = Xi[k]
                if a:
                    Yk = Y[k]
                    for j in rn:
                        acc[j] += a * Yk[j]
            res[i] = [x % mod for x in acc]
        return res

    def mpow(M, e, mod):
        m = len(M)
        R = [[0] * m for _ in range(m)]
        for i in range(m):
            R[i][i] = 1
        B = M
        while e:
            if e & 1:
                R = mul(R, B, mod)
            e >>= 1
            if e:
                B = mul(B, B, mod)
        return R

    K = 0
    for row in A:
        for x in row:
            if x == 0:
                K += 1

    Cp = mpow(A, p, p)

    D = [[0] * n for _ in range(n)]
    if p == 3:
        for i in range(n):
            for j in range(n):
                if A[i][j] == 0:
                    if i == j:
                        for jj in range(n):
                            v = A[i][jj]
                            if v:
                                D[i][jj] += v
                        for ii in range(n):
                            v = A[ii][i]
                            if v:
                                D[ii][i] += v
                    else:
                        v = A[j][i]
                        if v:
                            D[i][j] += v
    else:
        for r in range(n):
            if A[r][r] == 0:
                for j in range(n):
                    v = A[r][j]
                    if v:
                        D[r][j] += v
                for i in range(n):
                    v = A[i][r]
                    if v:
                        D[i][r] += v

    neg = (K & 1) == 1
    out_lines = []
    for i in range(n):
        row = []
        Ci = Cp[i]
        Di = D[i]
        for j in range(n):
            x = (Ci[j] + Di[j]) % p
            if neg:
                x = (-x) % p
            row.append(str(x))
        out_lines.append(' '.join(row))
    sys.stdout.write('\n'.join(out_lines))

