from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)

        def combine(a, b):
            if a is None:
                return b
            if b is None:
                return a
            asum, apref, asuff, abest = a
            bsum, bpref, bsuff, bbest = b
            return (
                asum + bsum,
                max(apref, asum + bpref),
                max(bsuff, bsum + asuff),
                max(abest, bbest, asuff + bpref),
            )

        size = 1
        while size < n:
            size <<= 1

        tree = [None] * (2 * size)
        for i, v in enumerate(nums):
            tree[size + i] = (v, v, v, v)
        for i in range(size - 1, 0, -1):
            tree[i] = combine(tree[i << 1], tree[i << 1 | 1])

        def query(l: int, r: int):
            # inclusive [l, r]
            l += size
            r += size + 1
            left = None
            right = None
            while l < r:
                if l & 1:
                    left = combine(left, tree[l])
                    l += 1
                if r & 1:
                    r -= 1
                    right = combine(tree[r], right)
                l >>= 1
                r >>= 1
            return combine(left, right)

        positions = {}
        for i, v in enumerate(nums):
            positions.setdefault(v, []).append(i)

        ans = query(0, n - 1)[3]

        for pos in positions.values():
            if len(pos) == n:
                continue  # deleting this value would empty the array

            acc = None
            prev = -1
            for p in pos:
                if prev + 1 <= p - 1:
                    acc = combine(acc, query(prev + 1, p - 1))
                prev = p
            if prev + 1 <= n - 1:
                acc = combine(acc, query(prev + 1, n - 1))

            if acc is not None and acc[3] > ans:
                ans = acc[3]

        return ans

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        N = n - 1
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact = [1] * (N + 1)
        invfact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        comb = fact[N] * invfact[k] % MOD * invfact[N - k] % MOD
        return comb * m % MOD * pow(m - 1, n - k - 1, MOD) % MOD

