class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        bits = [int(c) for c in s]

        def possible(limit: int) -> bool:
            INF = numOps + 1
            dp0 = [INF] * (limit + 1)
            dp1 = [INF] * (limit + 1)

            if bits[0] == 0:
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp1[1] = 0
                dp0[1] = 1

            for b in bits[1:]:
                ndp0 = [INF] * (limit + 1)
                ndp1 = [INF] * (limit + 1)

                for l in range(1, limit + 1):
                    cost = dp0[l]
                    if cost > numOps:
                        continue
                    if l < limit:
                        v = cost + (b != 0)
                        if v < ndp0[l + 1]:
                            ndp0[l + 1] = v
                    v = cost + (b != 1)
                    if v < ndp1[1]:
                        ndp1[1] = v

                for l in range(1, limit + 1):
                    cost = dp1[l]
                    if cost > numOps:
                        continue
                    if l < limit:
                        v = cost + (b != 1)
                        if v < ndp1[l + 1]:
                            ndp1[l + 1] = v
                    v = cost + (b != 0)
                    if v < ndp0[1]:
                        ndp0[1] = v

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

