def cycle_dist(P, X, N):
    dist = [-1] * (N + 1)
    cyc = []
    v = X
    while dist[v] == -1:
        dist[v] = 0
        cyc.append(v)
        v = P[v]
    L = len(cyc)
    for t, v in enumerate(cyc):
        dist[v] = 0 if t == 0 else L - t
    return dist, cyc


