        values = []
        isolated = 0

        for x in nums:
            if x > T:
                isolated += 1
            elif not present[x]:
                present[x] = 1
                values.append(x)

        if not values:
            return isolated
        if present[1]:
            return isolated + 1

        values.sort()
        dsu = DSU(T + 1)
        first_divisor = [-1] * (T + 1)

        for x in values:
            for m in range(x, T + 1, x):
                y = first_divisor[m]
                if y == -1:
                    first_divisor[m] = x
                else:
                    dsu.union(x, y)

        components = 0
        for x in values:
            if dsu.find(x) == x:
                components += 1

        return isolated + components
